48	public class MiniJournalCluster {
49	  public static final String CLUSTER_WAITACTIVE_URI = "waitactive";
50	  public static class Builder {
51	    private String baseDir;
52	    private int numJournalNodes = 3;
53	    private boolean format = true;
54	    private final Configuration conf;
55	
56	    static {
57	      DefaultMetricsSystem.setMiniClusterMode(true);
58	    }
