84	  private static final class JNInfo {
85	    private JournalNode node;
86	    private final InetSocketAddress ipcAddr;
87	    private final String httpServerURI;
88	
89	    private JNInfo(JournalNode node) {
90	      this.node = node;
91	      this.ipcAddr = node.getBoundIpcAddress();
92	      this.httpServerURI = node.getHttpServerURI();
93	    }
94	  }
95	
96	  private static final Logger LOG =
97	      LoggerFactory.getLogger(MiniJournalCluster.class);
98	  private final File baseDir;
99	  private final JNInfo[] nodes;
100	  
101	  private MiniJournalCluster(Builder b) throws IOException {
102	    LOG.info("Starting MiniJournalCluster with " +
103	        b.numJournalNodes + " journal nodes");
104	    
105	    if (b.baseDir != null) {
106	      this.baseDir = new File(b.baseDir);
107	    } else {
108	      this.baseDir = new File(MiniDFSCluster.getBaseDirectory());
109	    }
110	
111	    nodes = new JNInfo[b.numJournalNodes];
112	
113	    for (int i = 0; i < b.numJournalNodes; i++) {
114	      if (b.format) {
115	        File dir = getStorageDir(i);
116	        LOG.debug("Fully deleting JN directory " + dir);
117	        FileUtil.fullyDelete(dir);
118	      }
119	      JournalNode jn = new JournalNode();
120	      jn.setConf(createConfForNode(b, i));
121	      jn.start();
122	      nodes[i] = new JNInfo(jn);
123	    }
124	  }
