126	  /**
127	   * Set up the given Configuration object to point to the set of JournalNodes 
128	   * in this cluster.
129	   */
130	  public URI getQuorumJournalURI(String jid) {
131	    List<String> addrs = Lists.newArrayList();
132	    for (JNInfo info : nodes) {
133	      addrs.add("127.0.0.1:" + info.ipcAddr.getPort());
134	    }
135	    String addrsVal = Joiner.on(";").join(addrs);
136	    LOG.debug("Setting logger addresses to: " + addrsVal);
137	    try {
138	      return new URI("qjournal://" + addrsVal + "/" + jid);
139	    } catch (URISyntaxException e) {
140	      throw new AssertionError(e);
141	    }
142	  }
