153	  /**
154	   * Shutdown all of the JournalNodes in the cluster.
155	   * @throws IOException if one or more nodes failed to stop
156	   */
157	  public void shutdown() throws IOException {
158	    boolean failed = false;
159	    for (JNInfo info : nodes) {
160	      try {
161	        info.node.stopAndJoin(0);
162	      } catch (Exception e) {
163	        failed = true;
164	        LOG.warn("Unable to stop journal node " + info.node, e);
165	      }
166	    }
167	    if (failed) {
168	      throw new IOException("Unable to shut down. Check log for details");
169	    }
170	  }
