172	  private Configuration createConfForNode(Builder b, int idx) {
173	    Configuration conf = new Configuration(b.conf);
174	    File logDir = getStorageDir(idx);
175	    conf.set(DFSConfigKeys.DFS_JOURNALNODE_EDITS_DIR_KEY, logDir.toString());
176	    conf.set(DFSConfigKeys.DFS_JOURNALNODE_RPC_ADDRESS_KEY, "localhost:0");
177	    conf.set(DFSConfigKeys.DFS_JOURNALNODE_HTTP_ADDRESS_KEY, "localhost:0");
178	    return conf;
179	  }
