181	  public File getStorageDir(int idx) {
182	    return new File(baseDir, "journalnode-" + idx).getAbsoluteFile();
183	  }
184	  
185	  public File getJournalDir(int idx, String jid) {
186	    return new File(getStorageDir(idx), jid);
187	  }
