205	  public void restartJournalNode(int i) throws InterruptedException, IOException {
206	    JNInfo info = nodes[i];
207	    JournalNode jn = info.node;
208	    Configuration conf = new Configuration(jn.getConf());
209	    if (jn.isStarted()) {
210	      jn.stopAndJoin(0);
211	    }
212	    
213	    conf.set(DFSConfigKeys.DFS_JOURNALNODE_RPC_ADDRESS_KEY,
214	        NetUtils.getHostPortString(info.ipcAddr));
215	
216	    final String uri = info.httpServerURI;
217	    if (uri.startsWith("http://")) {
218	      conf.set(DFSConfigKeys.DFS_JOURNALNODE_HTTP_ADDRESS_KEY,
219	          uri.substring(("http://".length())));
220	    } else if (info.httpServerURI.startsWith("https://")) {
221	      conf.set(DFSConfigKeys.DFS_JOURNALNODE_HTTPS_ADDRESS_KEY,
222	          uri.substring(("https://".length())));
223	    }
224	
225	    JournalNode newJN = new JournalNode();
226	    newJN.setConf(conf);
227	    newJN.start();
228	    info.node = newJN;
229	  }
230	
231	  public int getQuorumSize() {
232	    return nodes.length / 2 + 1;
233	  }
234	
235	  public int getNumNodes() {
236	    return nodes.length;
237	  }
