239	  /**
240	   * Wait until all the journalnodes start.
241	   */
242	  public void waitActive() throws IOException {
243	    for (int i = 0; i < nodes.length; i++) {
244	      final int index = i;
245	      try {
246	        GenericTestUtils.waitFor(new Supplier<Boolean>() {
247	          // wait until all JN's IPC server is running
248	          @Override public Boolean get() {
249	            try {
250	              QuorumJournalManager qjm =
251	                  new QuorumJournalManager(nodes[index].node.getConf(),
252	                      getQuorumJournalURI(CLUSTER_WAITACTIVE_URI), FAKE_NSINFO);
253	              qjm.hasSomeData();
254	              qjm.close();
255	            } catch (IOException e) {
256	              // Exception from IPC call, likely due to server not ready yet.
257	              return false;
258	            }
259	            return true;
260	          }
261	        }, 50, 3000);
262	      } catch (TimeoutException e) {
263	        fail("Time out while waiting for journal node " + index + " to start.");
264	      } catch (InterruptedException ite) {
265	        LOG.warn("Thread interrupted when waiting for node start", ite);
266	      }
267	    }
268	  }
269	
270	  public void setNamenodeSharedEditsConf(String jid) {
271	    URI quorumJournalURI = getQuorumJournalURI(jid);
272	    for (int i = 0; i < nodes.length; i++) {
273	      nodes[i].node.getConf().set(DFSConfigKeys
274	          .DFS_NAMENODE_SHARED_EDITS_DIR_KEY, quorumJournalURI.toString());
275	    }
276	  }
277	}
