38	public class MiniQJMHACluster {
39	  private MiniDFSCluster cluster;
40	  private MiniJournalCluster journalCluster;
41	  private final Configuration conf;
42	  private static final Logger LOG =
43	      LoggerFactory.getLogger(MiniQJMHACluster.class);
44	
45	  public static final String NAMESERVICE = "ns1";
46	  private static final Random RANDOM = new Random();
47	
48	  public static class Builder {
49	    private final Configuration conf;
50	    private StartupOption startOpt = null;
51	    private int numNNs = 2;
52	    private final MiniDFSCluster.Builder dfsBuilder;
53	    private boolean forceRemoteEditsOnly = false;
54	    private String baseDir;
55	
56	    public Builder(Configuration conf) {
57	      this.conf = conf;
58	      // most QJMHACluster tests don't need DataNodes, so we'll make
59	      // this the default
60	      this.dfsBuilder = new MiniDFSCluster.Builder(conf).numDataNodes(0);
61	    }
