76	      this.baseDir = d;
77	      return this;
78	    }
79	
80	    public Builder setNumNameNodes(int nns) {
81	      this.numNNs = nns;
82	      return this;
83	    }
84	
85	    public Builder setForceRemoteEditsOnly(boolean val) {
86	      this.forceRemoteEditsOnly = val;
87	      return this;
88	    }
