91	  public static MiniDFSNNTopology createDefaultTopology(int nns, int startingPort) {
92	    MiniDFSNNTopology.NSConf nameservice = new MiniDFSNNTopology.NSConf(NAMESERVICE);
93	    for (int i = 0; i < nns; i++) {
94	      nameservice.addNN(new MiniDFSNNTopology.NNConf("nn" + i).setIpcPort(startingPort++)
95	          .setHttpPort(startingPort++));
96	    }
97	
98	    return new MiniDFSNNTopology().addNameservice(nameservice);
99	  }
100	
101	  public static MiniDFSNNTopology createDefaultTopology(int basePort) {
102	    return createDefaultTopology(2, basePort);
103	  }
104	
105	  private MiniQJMHACluster(Builder builder) throws IOException {
106	    this.conf = builder.conf;
107	    int retryCount = 0;
108	    int basePort = 10000;
109	
110	    while (true) {
111	      try {
112	        basePort = 10000 + RANDOM.nextInt(1000) * 4;
113	        LOG.info("Set MiniQJMHACluster basePort to " + basePort);
114	        // start 3 journal nodes
115	        journalCluster = new MiniJournalCluster.Builder(conf)
116	            .baseDir(builder.baseDir).format(true).build();
117	        journalCluster.waitActive();
118	        journalCluster.setNamenodeSharedEditsConf(NAMESERVICE);
119	        URI journalURI = journalCluster.getQuorumJournalURI(NAMESERVICE);
120	
121	        // start cluster with specified NameNodes
122	        MiniDFSNNTopology topology = createDefaultTopology(builder.numNNs, basePort);
123	
124	        initHAConf(journalURI, builder, basePort);
125	
126	        // First start up the NNs just to format the namespace. The MinIDFSCluster
127	        // has no way to just format the NameNodes without also starting them.
128	        cluster = builder.dfsBuilder.nnTopology(topology)
129	            .manageNameDfsSharedDirs(false).build();
130	        cluster.waitActive();
131	        cluster.shutdownNameNodes();
132	
133	        // initialize the journal nodes
134	        Configuration confNN0 = cluster.getConfiguration(0);
135	        NameNode.initializeSharedEdits(confNN0, true);
136	
137	        for (MiniDFSCluster.NameNodeInfo nn : cluster.getNameNodeInfos()) {
138	          nn.setStartOpt(builder.startOpt);
139	        }
140	
141	        // restart the cluster
142	        cluster.restartNameNodes();
143	        break;
144	      } catch (BindException e) {
145	        if (cluster != null) {
146	          cluster.shutdown(true);
147	          cluster = null;
148	        }
149	        ++retryCount;
150	        LOG.info("MiniQJMHACluster port conflicts, retried " +
151	            retryCount + " times");
152	      }
153	    }
154	  }
155	
156	  private Configuration initHAConf(URI journalURI, Builder builder,
157	      int basePort) {
158	    conf.set(DFSConfigKeys.DFS_NAMENODE_SHARED_EDITS_DIR_KEY,
159	        journalURI.toString());
160	    if (builder.forceRemoteEditsOnly) {
161	      conf.set(DFSConfigKeys.DFS_NAMENODE_EDITS_DIR_KEY, journalURI.toString());
162	      conf.set(DFSConfigKeys.DFS_NAMENODE_EDITS_DIR_REQUIRED_KEY,
163	          journalURI.toString());
164	    }
165	
166	    List<String> nns = new ArrayList<>(builder.numNNs);
167	    int port = basePort;
168	    for (int i = 0; i < builder.numNNs; i++) {
169	      nns.add("127.0.0.1:" + port);
170	      // increment by 2 each time to account for the http port in the config setting
171	      port += 2;
172	    }
173	
174	    // use standard failover configurations
175	    HATestUtil.setFailoverConfigurations(conf, NAMESERVICE, nns,
176	        ConfiguredFailoverProxyProvider.class);
177	    return conf;
178	  }
179	
180	  public MiniDFSCluster getDfsCluster() {
181	    return cluster;
182	  }
183	
184	  public MiniJournalCluster getJournalCluster() {
185	    return journalCluster;
186	  }
187	
188	  public void shutdown() throws IOException {
189	    cluster.shutdown();
190	    journalCluster.shutdown();
191	  }
192	}
