+      URI uri = jCluster.getQuorumJournalURI("myjournal");
+      String[] addrs = uri.getAuthority().split(";");
+      assertEquals(3, addrs.length);
+
+      assertEquals(8481,
+          jCluster.getJournalNode(0).getHttpAddress().getPort());
+      assertEquals(8482,
+          jCluster.getJournalNode(1).getHttpAddress().getPort());
+      assertEquals(8483,
+          jCluster.getJournalNode(2).getHttpAddress().getPort());
+
+      assertEquals(8491,
+          jCluster.getJournalNode(0).getRpcServer().getAddress().getPort());
+      assertEquals(8492,
+          jCluster.getJournalNode(1).getRpcServer().getAddress().getPort());
+      assertEquals(8493,
+          jCluster.getJournalNode(2).getRpcServer().getAddress().getPort());
+
+      JournalNode node = jCluster.getJournalNode(0);
